#[cfg(test)]
mod tests {
    use ackplane_protocol::supervisor::{
        SupervisorCapabilities, SupervisorDirectiveCapability, SupervisorIdentity,
        SupervisorLifecycleReason, SupervisorLifecycleReceipt, SupervisorOutboxDurability,
        SupervisorRegistration, SupervisorRuntime, SupervisorSession, SupervisorWorkerState,
    };

    use super::*;

    fn unique_scope(label: &str) -> (String, String, String) {
        let mut bytes = [0_u8; 8];
        getrandom::getrandom(&mut bytes).expect("the OS random source should be available");
        let suffix: String = bytes.iter().map(|byte| format!("{byte:02x}")).collect();
        (
            format!("tenant-supervisor-{label}-{suffix}"),
            format!("repository-supervisor-{label}-{suffix}"),
            format!("supervisor-{label}-{suffix}"),
        )
    }

    fn registration(
        tenant_id: String,
        repository_id: String,
        supervisor_id: String,
    ) -> SupervisorRegistration {
        SupervisorRegistration {
            supervisor_id,
            identity: SupervisorIdentity {
                tenant_id,
                repository_id,
                node_id: "node:integration".to_string(),
            },
            supervisor_version: "1.0.0".to_string(),
            protocol_version: "v1".to_string(),
            capabilities: SupervisorCapabilities {
                supported_directives: vec![
                    SupervisorDirectiveCapability::Notify,
                    SupervisorDirectiveCapability::Pause,
                ],
                supports_checkpoint: true,
                supports_force_termination: false,
                outbox_durability: SupervisorOutboxDurability::Persistent,
                recoverable_outbox: true,
            },
        }
    }

    fn session(supervisor_id: String) -> SupervisorSession {
        SupervisorSession {
            session_id: "session:integration".to_string(),
            supervisor_id,
            worker_id: "worker:integration".to_string(),
            runtime: SupervisorRuntime::Service,
            started_at: 1_000,
            state: SupervisorWorkerState::Started,
        }
    }

    async fn store() -> Option<SupervisorStore> {
        let pool = crate::test_support::test_pool()?;
        Some(SupervisorStore::connect(&pool).await.unwrap())
    }

    #[tokio::test]
    async fn registration_retries_return_the_original_projection_and_refuse_changed_content() {
        let Some(store) = store().await else {
            println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
            return;
        };
        let (tenant_id, repository_id, supervisor_id) = unique_scope("registration");
        let registration = registration(tenant_id.clone(), repository_id.clone(), supervisor_id);

        let first = store
            .register(&registration)
            .await
            .expect("register supervisor");
        assert!(!first.idempotent_replay);
        assert_eq!(first.status.registration, registration);
        assert_eq!(first.status.freshness, SupervisorFreshness::NeverReported);

        let replay = store
            .register(&registration)
            .await
            .expect("replay registration");
        assert!(replay.idempotent_replay);
        assert_eq!(replay.status.registration, registration);

        let mut changed = registration.clone();
        changed.supervisor_version = "2.0.0".to_string();
        assert!(matches!(
            store.register(&changed).await,
            Err(SupervisorStoreError::RegistrationConflict)
        ));
    }

    #[tokio::test]
    async fn supervisor_lists_are_tenant_scoped() {
        let Some(store) = store().await else {
            println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
            return;
        };
        let (tenant_id, repository_id, supervisor_id) = unique_scope("tenant-scope");
        store
            .register(&registration(
                tenant_id,
                repository_id.clone(),
                supervisor_id,
            ))
            .await
            .expect("register supervisor");
        assert_eq!(
            store
                .list_supervisors_at(
                    "foreign-tenant",
                    &repository_id,
                    1_000,
                    HEARTBEAT_STALE_AFTER_SECS,
                )
                .await
                .expect("foreign tenant list"),
            Vec::<SupervisorStatus>::new()
        );
    }

    #[tokio::test]
    async fn session_lookup_stays_within_its_tenant_and_repository() {
        let Some(store) = store().await else {
            println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
            return;
        };
        let (tenant_id, repository_id, supervisor_id) = unique_scope("session-lookup");
        let registration = registration(tenant_id.clone(), repository_id.clone(), supervisor_id);
        let session = session(registration.supervisor_id.clone());
        store
            .register(&registration)
            .await
            .expect("register supervisor");
        let expected = store
            .record_session(&tenant_id, &repository_id, &session)
            .await
            .expect("record supervisor session")
            .projection;

        assert_eq!(
            store
                .session(&tenant_id, &repository_id, &session.session_id)
                .await
                .expect("resolve scoped session"),
            Some(expected)
        );
        assert_eq!(
            store
                .session("foreign-tenant", &repository_id, &session.session_id)
                .await
                .expect("foreign session lookup"),
            None
        );
    }

    #[tokio::test]
    async fn heartbeat_freshness_uses_server_time_without_regressing() {
        let Some(store) = store().await else {
            println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
            return;
        };
        let (tenant_id, repository_id, supervisor_id) = unique_scope("heartbeat");
        let registration = registration(
            tenant_id.clone(),
            repository_id.clone(),
            supervisor_id.clone(),
        );
        store
            .register(&registration)
            .await
            .expect("register supervisor");

        store
            .record_heartbeat_at(&tenant_id, &repository_id, &supervisor_id, 1_000)
            .await
            .expect("record heartbeat");
        let current = store
            .list_supervisors_at(
                &tenant_id,
                &repository_id,
                1_090,
                HEARTBEAT_STALE_AFTER_SECS,
            )
            .await
            .expect("read current heartbeat");
        assert_eq!(current[0].freshness, SupervisorFreshness::Current);

        store
            .record_heartbeat_at(&tenant_id, &repository_id, &supervisor_id, 900)
            .await
            .expect("record stale heartbeat");
        let stale = store
            .list_supervisors_at(
                &tenant_id,
                &repository_id,
                1_091,
                HEARTBEAT_STALE_AFTER_SECS,
            )
            .await
            .expect("read stale heartbeat");
        assert_eq!(stale[0].last_heartbeat_at, Some(1_000));
        assert_eq!(stale[0].freshness, SupervisorFreshness::Stale);
    }

    #[tokio::test]
    async fn lifecycle_receipts_replay_without_regressing_the_current_session() {
        let Some(store) = store().await else {
            println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
            return;
        };
        let (tenant_id, repository_id, supervisor_id) = unique_scope("lifecycle");
        let registration = registration(
            tenant_id.clone(),
            repository_id.clone(),
            supervisor_id.clone(),
        );
        store
            .register(&registration)
            .await
            .expect("register supervisor");
        let session = session(supervisor_id);
        store
            .record_session(&tenant_id, &repository_id, &session)
            .await
            .expect("record session");
        let paused_request = SupervisorLifecycleReceiptRequest {
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
            receipt: SupervisorLifecycleReceipt {
                supervisor_id: session.supervisor_id.clone(),
                session_id: session.session_id.clone(),
                worker_id: session.worker_id.clone(),
                occurred_at: 1_100,
                state: SupervisorWorkerState::Paused,
                reason: Some(SupervisorLifecycleReason::DirectiveExpired),
            },
            idempotency_key: "receipt:paused".to_string(),
        };
        let paused = store
            .record_lifecycle(&paused_request)
            .await
            .expect("append pause receipt");
        assert!(!paused.idempotent_replay);
        assert!(paused.projection_advanced);
        assert_eq!(
            paused.projection.session.state,
            SupervisorWorkerState::Paused
        );
        assert_eq!(
            paused.projection.current_reason,
            Some(SupervisorLifecycleReason::DirectiveExpired)
        );

        let replay = store
            .record_lifecycle(&paused_request)
            .await
            .expect("replay pause receipt");
        assert!(replay.idempotent_replay);
        assert!(!replay.projection_advanced);
        assert_eq!(replay.receipt, paused.receipt);
        assert_eq!(replay.projection, paused.projection);

        let mut changed = paused_request.clone();
        changed.receipt.state = SupervisorWorkerState::Draining;
        assert!(matches!(
            store.record_lifecycle(&changed).await,
            Err(SupervisorStoreError::IdempotencyConflict)
        ));

        let older_request = SupervisorLifecycleReceiptRequest {
            idempotency_key: "receipt:older".to_string(),
            receipt: SupervisorLifecycleReceipt {
                state: SupervisorWorkerState::Draining,
                occurred_at: 1_050,
                reason: None,
                ..paused_request.receipt.clone()
            },
            ..paused_request
        };
        let older = store
            .record_lifecycle(&older_request)
            .await
            .expect("append older lifecycle receipt");
        assert!(!older.projection_advanced);
        assert_eq!(older.projection, paused.projection);
        assert_eq!(
            store
                .lifecycle_history(&tenant_id, &repository_id, &session.session_id)
                .await
                .expect("read lifecycle history"),
            vec![paused.receipt, older.receipt]
        );
    }

    /// ADR-0146 decision 3: the recorded position advances only upward, and
    /// only from a value the supervisor stated.
    ///
    /// The upward-only rule is what makes a resend safe. A supervisor that
    /// re-sends an older queued frame after a dropped connection restates an
    /// older sequence; if that overwrote the recorded position, the server
    /// would tell the *next* connection it had accepted less than it really
    /// had, and `reconcile` would answer `Resend` for frames already durably
    /// held -- or, in the opposite direction, mask a genuine
    /// `IncompleteEvidence` by walking its own position back below the
    /// supervisor's.
    #[tokio::test]
    async fn an_accepted_outbox_position_advances_only_upward() {
        let Some(store) = store().await else {
            println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
            return;
        };
        let (tenant_id, repository_id, supervisor_id) = unique_scope("outbox-position");
        store
            .register(&registration(
                tenant_id.clone(),
                repository_id.clone(),
                supervisor_id.clone(),
            ))
            .await
            .expect("register supervisor");

        // Nothing sequenced accepted yet: the server states no position rather
        // than inventing a zero.
        assert_eq!(
            store
                .accepted_outbox_sequence(&tenant_id, &repository_id, &supervisor_id)
                .await
                .expect("read an unset position"),
            None
        );

        assert_eq!(
            store
                .record_outbox_sequence(&tenant_id, &repository_id, &supervisor_id, 4)
                .await
                .expect("record the first position"),
            4
        );
        assert_eq!(
            store
                .record_outbox_sequence(&tenant_id, &repository_id, &supervisor_id, 7)
                .await
                .expect("record a later position"),
            7
        );
        // A resend of an older frame must not walk the position backwards.
        assert_eq!(
            store
                .record_outbox_sequence(&tenant_id, &repository_id, &supervisor_id, 2)
                .await
                .expect("record a resent older position"),
            7
        );
        assert_eq!(
            store
                .accepted_outbox_sequence(&tenant_id, &repository_id, &supervisor_id)
                .await
                .expect("read the recorded position"),
            Some(7)
        );
    }

    /// A position is scoped to one supervisor in one repository. Reading it
    /// for a different supervisor must not borrow another's evidence.
    #[tokio::test]
    async fn accepted_outbox_positions_are_scoped_per_supervisor() {
        let Some(store) = store().await else {
            println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
            return;
        };
        let (tenant_id, repository_id, supervisor_id) = unique_scope("outbox-scope");
        let (_, _, other_supervisor_id) = unique_scope("outbox-scope-other");
        for id in [&supervisor_id, &other_supervisor_id] {
            store
                .register(&registration(
                    tenant_id.clone(),
                    repository_id.clone(),
                    id.clone(),
                ))
                .await
                .expect("register supervisor");
        }

        store
            .record_outbox_sequence(&tenant_id, &repository_id, &supervisor_id, 11)
            .await
            .expect("record a position");

        assert_eq!(
            store
                .accepted_outbox_sequence(&tenant_id, &repository_id, &other_supervisor_id)
                .await
                .expect("read the other supervisor's position"),
            None
        );
    }
}
